<style lang="scss" scoped src="./donation-detail-button-block.scss"></style>

<script>
import { Component, Vue } from "vue-property-decorator";
import Button from "../../components/button/button";
import {
  ButtonSize,
  ButtonMode
} from "../../components/button/button.constants";

@Component({
  components: {
    Button
  }
})
export default class DonationDetailButtonBlock extends Vue { 
  ButtonSize = ButtonSize;
  ButtonMode = ButtonMode;

  handleResendReceipt() {
    /**
     * Event when users click resend receipt
     * @event send
     */
    this.$emit("send");
  }

  handleSendRefund() {
    /**
     * Event when users click resend receipt
     * @event refund
     */
    this.$emit("refund");
  }

  handleCancel() {
    /**
     * Event when users click Cancel Transaction;
     * @event cancel
     */
    this.$emit("cancel");
  }

  handleUpdate() {
    /**
     * Event when users click Update Notes or Anonymity
     * @event update
     */
    this.$emit("update");
  }
}
</script>

<template>
  <div class="DonationDetailButtonBlock">
    <Button
      :mode="ButtonMode.GMS_SUBTLE"
      :size="ButtonSize.LARGE"
      label="Resend Receipt"
      @click="handleResendReceipt"
    />
    <Button
      :mode="ButtonMode.GMS_SUBTLE"
      :size="ButtonSize.LARGE"
      label="Send Refund"
      @click="handleSendRefund"
    />
    <Button
      :mode="ButtonMode.GMS_SUBTLE"
      :size="ButtonSize.LARGE"
      label="Cancel Transaction"
      @click="handleCancel"
    />
    <Button
      :mode="ButtonMode.GMS_SUBTLE"
      :size="ButtonSize.LARGE"
      label="Update Notes or Anonymity"
      @click="handleUpdate"
    />
  </div>
</template>
